use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/g2-queue-scan-count175";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn function(s:&str,needle:&str)->String{let start=s.find(needle).unwrap();let brace=s[start..].find('{').unwrap()+start;let mut level=0;for(i,b)in s.as_bytes().iter().enumerate().skip(brace){if *b==b'{'{level+=1}if *b==b'}'{level-=1;if level==0{return s[start..=i].to_string()}}}panic!("unclosed function")}
fn main(){let r=Path::new(R);assert!(!r.join("plan.json").exists());let frozen=read("/home/ubuntu/src/zopro-perf-work/balanced-kh-production/frozen-candidate.json");let manifest=read(format!("{Z}/docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json"));let mut pins=BTreeMap::new();for(p,h)in frozen["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins.insert(p.clone(),h.as_str().unwrap().to_string());}for(p,h)in manifest["source_files_sha256"].as_object().unwrap(){let q=Path::new(Z).join(p);assert_eq!(hash(&q),h.as_str().unwrap());pins.insert(q.display().to_string(),h.as_str().unwrap().to_string());}
 let phi=fs::read_to_string(format!("{Z}/crates/zopro-core/src/msm_affine/g2_phi.rs")).unwrap();let start=phi.find("const C1:").unwrap();let end=phi[start..].find("use zopro_bn254::{Fq,").unwrap()+start;let mut split=phi[start..end].to_string();let msm=fs::read_to_string(format!("{Z}/crates/zopro-core/src/msm_affine.rs")).unwrap();split.push_str(&function(&msm,"fn booth_digit("));split.push_str("\nfn digit(words:&[u64;4],w:usize,bits:usize)->i16{booth_digit(words,w,bits)}\n");let borrowed=fs::read_to_string(format!("{Z}/crates/zopro-core/src/msm_affine/g2_borrowed.rs")).unwrap();split.push_str(&function(&borrowed,"fn component("));split.push_str("\npub fn phi_lambda()->zopro_bn254::Fr {use zopro_bn254::Fr;let a=Fr::from_le_bytes_mod_order(&V1X.to_le_bytes());let b=Fr::from_le_bytes_mod_order(&V1Y_ABS.to_le_bytes());a*b.inverse().unwrap()}\npub fn digit_of(s:&[u64;4],high:bool,w:usize,bits:usize)->i16{component(s,high,w,bits)}\n");fs::write(r.join("split.rs"),split).unwrap();fs::write(r.join("lifo-method.rs"),function(&borrowed,"fn take_from_queue(")).unwrap();
 let input="/home/ubuntu/src/zopro-perf-work/wire-union-census175/cases.json";fs::copy(input,r.join("cases.json")).unwrap();let old="/home/ubuntu/src/zopro-perf-work/wire-union-census175/analysis.json";fs::copy(old,r.join("inherited-eligibility.json")).unwrap();pins.insert(input.into(),hash(input));pins.insert(old.into(),hash(old));for case in read(input).as_array().unwrap().iter().take(2){for k in["key","request"]{let p=case[k].as_str().unwrap();pins.insert(p.into(),hash(p));}}
 let dir=Path::new(frozen["libraries"]["zopro_core"].as_str().unwrap()).parent().unwrap();let mut args=vec!["rustc".into(),"--edition=2021".into(),"-O".into(),"-C".into(),"target-cpu=native".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",dir.display())];for(n,p)in frozen["libraries"].as_object().unwrap(){args.extend(["--extern".into(),format!("{n}={}",p.as_str().unwrap())]);}args.push(r.join("probe.rs").display().to_string());let mut tests=args.clone();tests.extend(["--test".into(),"-o".into(),r.join("tests").display().to_string()]);args.extend(["-o".into(),r.join("probe").display().to_string()]);for p in["setup.rs","setup","model.rs","probe.rs","design.md","split.rs","lifo-method.rs","cases.json","inherited-eligibility.json"]{let q=r.join(p);pins.insert(q.display().to_string(),hash(q));}let save=|p:&str,v:&Value|fs::write(r.join(p),serde_json::to_vec_pretty(v).unwrap()).unwrap();save("pins.json",&json!(pins));let step=|n:&str,a:Vec<String>|json!({"kind":"command","name":n,"argv":a,"timeout_seconds":900});save("plan.json",&json!({"version":1,"source_pins":r.join("pins.json"),"steps":[step("compile-tests",tests),step("test-model",vec![r.join("tests").display().to_string(),"--test-threads=1".into()]),step("compile-probe",args),{"kind":"command","name":"count-real-inputs","argv":[r.join("probe"),r.join("cases.json")],"timeout_seconds":900,"environment":manifest["environment"]}]}));println!("Prepared4-step ordinary queue count screen;no prover rebuild or proof run");}
